function loadOne(k){var b=biz();var q=sb().from(T[k]).select('*').eq('business_id',b.id);if(k==='curriculum')return q.maybeSingle().then(function(r){if(r.error)throw r.error;data[k]=r.data||null});return q.order('created_at',{ascending:false}).limit(500).then(function(r){if(r.error)throw r.error;data[k]=r.data||[]})}
