if(tab==='overview'){var due=f.filter(function(x){return x.status==='unpaid'||x.status==='part_paid'}).reduce(function(n,x){return n+Number(x.amount||0)},0);return '<div class="wls-stats"><div class="wls-stat"><small>Active students</small><strong>'+s.filter(function(x){return x.status==='active'}).length+'</strong><span>Current enrolments</span></div><div class="wls-stat"><small>Active classes</small><strong>'+c.filter(function(x){return x.is_active}).length+'</strong><span>Academic groups</span></div><div class="wls-stat"><small>Fee invoices</small><strong>'+f.length+'</strong><span>Recorded invoices</span></div><div class="wls-stat"><small>Outstanding fees</small><strong>'+new Intl.NumberFormat('en-SL',{style:'currency',currency:'SLE',maximumFractionDigits:0}).format(due)+'</strong><span>Unpaid / part paid</span></div></div><div class="wls-grid"><div class="wls-panel"><div class="wls-panel-head"><div><h3>Recently admitted students</h3><div class="wls-muted">Latest student registrations</div></div><button class="wls-btn alt" data-tab="students">View register</button></div>'+tbl(['Admission no.','Student','Class','Status'],s.slice(0,5).map(function(x){return '<tr><td>'+esc(x.admission_number)+'</td><td><b>'+esc(x.first_name+' '+x.last_name)+'</b></td><td>'+esc((c.find(function(y){return y.id===x.class_id})||{}).name||'Unassigned')+'</td><td><span class="wls-pill">'+esc(x.status)+'</span></td></tr>'}).join(''))+'</div><div class="wls-panel"><h3>Academic operations</h3><p class="wls-muted">Manage student records, class structures, daily attendance and fee administration from one workspace.</p><div style="display:grid;gap:9px;margin-top:17px"><button class="wls-btn alt" data-tab="attendance">Take attendance</button><button class="wls-btn alt" data-tab="fees">Manage school fees</button><button class="wls-btn alt" data-tab="exams">Exams & results</button></div></div></div>'}
